pub(super) unsafe fn init(
    base: PageAligned<PhysicalAddress>,
    bitmap: Bitmap,
) -> Result<Kpool, Error> {
    if unlikely(INSTANCE_INIT.load(ORDER)) {
        return Err(Error::new(ErrorCode::InvalidArgument, "kernel pool already initialized"));
